class Solution {
  public String[] largestString(int[] nums) {
    String[] res = new String[nums.length];
    for (int i = 0; i < nums.length; i++) {
      long x = nums[i];
      StringBuilder sb = new StringBuilder();
      long zs = x >> 25;
      for (long t = 0; t < zs; t++) sb.append('z');
      long rem = x & ((1L << 25) - 1);
      for (int b = 24; b >= 0; b--) if ((rem >> b & 1) != 0) sb.append((char) ('a' + b));
      res[i] = sb.toString();
    }
    return res;
  }
}
